-- zoom src: https://www.reddit.com/r/hyprland/comments/1c61h25/screen_magnification_zooming_on_wayland/

hl.bind(
	mod .. " + " .. mod2 .. " + " .. "mouse_down",
	hl.dsp.exec_cmd(
		"hyprctl keyword cursor:zoom_factor \"$(hyprctl getoption cursor:zoom_factor | awk 'NR==1 {factor = $2; if (factor < 1) {factor = 1}; print factor * 1.25}')\""
	)
)

hl.bind(
	mod .. " + " .. mod2 .. " + " .. "mouse_up",
	hl.dsp.exec_cmd(
		"hyprctl keyword cursor:zoom_factor \"$(hyprctl getoption cursor:zoom_factor | awk 'NR==1 {factor = $2; if (factor < 1) {factor = 1}; print factor / 1.25}')\""
	)
)

