-- audio and brightness controls for gamemode

hl.define_submap("gamemode", function()
	hl.bind(
		"XF86MonBrightnessUp",
		hl.dsp.exec_cmd("$script_dir/volume_brightness.sh brightness_up"),
		{ repeating = true, locked = true }
	)
	hl.bind(
		"XF86MonBrightnessDown",
		hl.dsp.exec_cmd("$script_dir/volume_brightness.sh brightness_down"),
		{ repeating = true, locked = true }
	)
	hl.bind(
		"XF86AudioRaiseVolume",
		hl.dsp.exec_cmd("$script_dir/volume_brightness.sh volume_up"),
		{ repeating = true, locked = true }
	)
	hl.bind(
		"XF86AudioLowerVolume",
		hl.dsp.exec_cmd("$script_dir/volume_brightness.sh volume_down"),
		{ repeating = true, locked = true }
	)
	hl.bind(
		"XF86AudioMute",
		hl.dsp.exec_cmd("$script_dir/volume_brightness.sh volume_mute"),
		{ repeating = true, locked = true }
	)
	hl.bind(
		"XF86AudioMicMute",
		hl.dsp.exec_cmd("wpctl set-mute @DEFAULT_AUDIO_SOURCE@ toggle"),
		{ repeating = true, locked = true }
	)
	hl.bind("XF86AudioNext", hl.dsp.exec_cmd("playerctl next"), { locked = true })
	hl.bind("XF86AudioPause", hl.dsp.exec_cmd("playerctl play-pause"), { locked = true })
	hl.bind("XF86AudioPlay", hl.dsp.exec_cmd("playerctl play-pause"), { locked = true })
	hl.bind("XF86AudioPrev", hl.dsp.exec_cmd("playerctl previous"), { locked = true })
end)
